function validate([coins, edges]) {
  const n = coins.length;
  if (n < 1 || n > 30000) return 'coins needs 1 to 30000 entries.';
  if (coins.some(c => c !== 0 && c !== 1)) return 'Each coins[i] is 0 or 1.';
  if (!Array.isArray(edges) || edges.length !== n - 1) return 'edges must have exactly n - 1 pairs.';
  const root = Array.from({ length: n }, (_, i) => i);
  const find = (x) => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  for (const e of edges) {
    if (!Array.isArray(e) || e.length !== 2) return 'Each edge is a pair [a, b].';
    const [a, b] = e;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 0 || b < 0 || a >= n || b >= n) return 'Edge ends must be node labels from 0 to n - 1.';
    if (a === b) return 'An edge cannot join a node to itself.';
    const ra = find(a), rb = find(b);
    if (ra === rb) return 'edges must form a tree (no cycles).';
    root[ra] = rb;
  }
  return null;
}

