function collectTheCoins(coins, edges) {
  const n = coins.length;
  const graph = Array.from({ length: n }, () => []);
  const degree = new Array(n).fill(0);
  for (const [a, b] of edges) {
    graph[a].push(b);
    graph[b].push(a);
    degree[a]++;
    degree[b]++;
  }
  let remaining = n;

  const queue = [];
  for (let node = 0; node < n; node++) {
    if (degree[node] === 1 && coins[node] === 0) queue.push(node);
  }
  let head = 0;
  while (head < queue.length) {
    const leaf = queue[head++];
    degree[leaf] = 0;
    remaining--;
    for (const next of graph[leaf]) {
      if (degree[next] === 0) continue;
      degree[next]--;
      if (degree[next] === 1 && coins[next] === 0) queue.push(next);
    }
  }

  for (let round = 0; round < 2; round++) {
    const leaves = [];
    for (let node = 0; node < n; node++) {
      if (degree[node] === 1) leaves.push(node);
    }
    for (const leaf of leaves) {
      degree[leaf] = 0;
      remaining--;
      for (const next of graph[leaf]) {
        if (degree[next] > 0) degree[next]--;
      }
    }
  }
  return Math.max(0, remaining - 1) * 2;
}

