function collectTheCoins(coins, edges) {
  // Try every connected set of nodes to walk around; a closed walk covering a
  // connected set of m nodes costs 2 * (m - 1) crossings.
  const n = coins.length;
  const adj = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }
  const dist = [];
  for (let s = 0; s < n; s++) {
    const d = new Array(n).fill(-1);
    d[s] = 0;
    const q = [s];
    for (let i = 0; i < q.length; i++) for (const t of adj[q[i]]) if (d[t] < 0) { d[t] = d[q[i]] + 1; q.push(t); }
    dist.push(d);
  }
  let best = Infinity;
  for (let mask = 1; mask < (1 << n); mask++) {
    const members = [];
    for (let i = 0; i < n; i++) if (mask & (1 << i)) members.push(i);
    // connected?
    const seen = new Set([members[0]]);
    const stack = [members[0]];
    while (stack.length) {
      const u = stack.pop();
      for (const v of adj[u]) if ((mask & (1 << v)) && !seen.has(v)) { seen.add(v); stack.push(v); }
    }
    if (seen.size !== members.length) continue;
    let covered = true;
    for (let c = 0; c < n && covered; c++) {
      if (coins[c] === 1 && !members.some(m => dist[m][c] <= 2)) covered = false;
    }
    if (covered) best = Math.min(best, 2 * (members.length - 1));
  }
  return best;
}

