function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'small' ? pick(1, 10) : 2000;
  const shape = pick(0, 2);
  const parent = [-1];
  for (let i = 1; i < n; i++) {
    if (shape === 0) parent.push(pick(0, i - 1));
    else if (shape === 1) parent.push(rand() < 0.85 ? i - 1 : pick(0, i - 1));
    else parent.push(pick(Math.max(0, i - 3), i - 1));
  }
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = pick(0, i); [order[i], order[j]] = [order[j], order[i]]; }
  const edges = [];
  for (let i = 1; i < n; i++) edges.push(rand() < 0.5 ? [order[i], order[parent[i]]] : [order[parent[i]], order[i]]);
  for (let i = edges.length - 1; i > 0; i--) { const j = pick(0, i); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  const density = [0.05, 0.2, 0.5, 0.9][pick(0, 3)];
  const coins = Array.from({ length: n }, () => (rand() < density ? 1 : 0));
  return [coins, edges];
}
